de, s.phone, s.name, s.email, s.shipping_last_update_date, COALESCE(s.sku_code, c.Parent_SKU) AS SKU, s.product_id, s.product_name, s.currency, s.City, s.State, s.order_status, s.Order_Date, s.Order_Time, CASE WHEN cc.child_number_rows IS NOT NULL THEN s.quantity / cc.child_number_rows ELSE s.quantity END AS quantity, CASE WHEN cc.child_number_rows IS NOT NULL THEN s.gross_sales_before_tax / cc.child_number_rows ELSE s.gross_sales_before_tax END AS gross_sales_before_tax, CASE WHEN cc.child_number_rows IS NOT NULL THEN s.gross_sales_after_tax / cc.child_number_rows ELSE s.gross_sales_after_tax END AS gross_sales_after_tax, s.dis, s.discount, s.tax, s.shipping_price, CASE WHEN cc.child_number_rows IS NOT NULL THEN Round(cast(s.selling_price as float64),2) / cc.child_number_rows ELSE s.selling_price END AS selling_price, s.oms_order_status, s.shipping_status, s.final_shipping_status, s.saleorderitemcode, s.sales_order_item_id, s.awb, s.payment_gateway, s.payment_mode, s.courier, s.dispatch_date, s.delivered_date, s.delivered_status, s.return_flag, s.returned_quantity, s.returned_sales, s.cancelled_quantity, s.new_customer_flag, s.acquisition_product, s.days_in_shipment, s.MARKETPLACE_ACQUISITION_DATE, s.SKU_CODE, s.product_name_final, s.product_category, s.product_sub_category, s.commonsku, s.warehouse, s.pincode, s.source_pincode, s.discount_codes, s.nature, s.refund_date, s.refund_value, s.cancelled_at, s.final_channel_type, s.final_utm_campaign, c.Child_sku, s.quantity * c.child_quantity as child_quantity, ps.Primary_Channel b2b_customer, s.courier_aggregator FROM maplemonk.prolicious_wh_sales_consolidated_intermediate_pre s LEFT JOIN maplemonk.prolicious_parent_child_sku_mapping_fact_items c ON c.Parent_SKU = s.sku_code LEFT JOIN child_count cc ON cc.Parent_SKU = s.sku_code left join ( select replace(upper(B2B_Customer_Names),\' \',\'\') as Customer_Name, upper(Mapped_Primary_Sales_Channel) as Primary_Channel from Maplemonk.Prolicious_Primary_Sales_Customer_Name_Mapping qualify row_number() over(partition by replace(upper(B2B_Customer_Names),\' \',\'\') order by 1 desc) = 1 )ps on replace(upper(s.name),\' \',\'\') = replace(upper(ps.Customer_Name),\' \',\'\') ; CREATE OR REPLACE TABLE prolicious-wh.Maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.*, g.mapped_city, g.mapped_state FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM prolicious-wh.Maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM prolicious-wh.Maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN prolicious-wh.Maplemonk.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace) LEFT JOIN ( SELECT upper(trim(city_names)) as city_name, upper(trim(mapped_city)) as mapped_city, upper(trim(mapped_state)) as mapped_state FROM prolicious-wh.`Maplemonk.GS_Prolicious_City_Mapping` qualify row_number() over (partition by upper(trim(city_names)) order by 1 desc) = 1 ) g ON upper(g.city_name) = upper(m.city) Where lower(m.marketplace) not like \'%offline%\' ; ALTER TABLE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id order by order_date) rw FROM prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id = B.customer_id and rw =1; UPDATE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id order by order_date) rw FROM prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id= B.customer_id and rw=1; UPDATE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id, channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id, order_date, channel, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id) AS firstOrderDate, row_number() over (partition by customer_id order by ORDER_TIME) rw FROM prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id = b.customer_id; UPDATE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id = b.customer_id; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id, product_name_final FROM ( SELECT customer_id, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id) firstOrderdate, row_number() over (partition by customer_id order by ORDER_TIME asc, selling_price desc) rw FROM prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id = B.customer_id; UPDATE prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' ELSE state END WHERE UPPER(state) IN ( \'AP\', \'AR\', \'AS\', \'BR\', \'CT\', \'GA\', \'GJ\', \'HR\', \'HP\', \'JH\', \'KA\', \'KL\', \'MP\', \'MH\', \'MN\', \'ML\', \'MZ\', \'NL\', \'OR\', \'PB\', \'RJ\', \'SK\', \'TN\', \'TS\', \'TL\', \'TR\', \'UP\', \'UT\', \'UK\', \'WB\', \'AN\', \'CH\', \'DN\', \'DD\', \'LD\', \'DL\', \'PY\', \'JK\', \'JAMMU & KASHMIR\', \'ANDAMAN & NICOBAR ISLANDS\' ); create or replace table prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated as select final_marketplace, customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, RTO_flag, DTO_flag, RTO_value, DTO_value, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, GROSS_SALES_AFTER_TAX, dis, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, Payment_Mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, nature, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, refund_date, refund_value, cancelled_at, b2b_customer, null as shopify_refund_value, null as return_tax, null as return_reference_code, final_channel_type, final_utm_campaign, child_sku, courier_aggregator, mapped_city, mapped_state, pack_type from maplemonk.prolicious_wh_sales_consolidated union all ( select null final_marketplace, null customer_id_final, null acquisition_date, null first_complete_order_date, null Order_Quantity, null RTO_flag, null DTO_flag, null RTO_value, null DTO_value, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, null ORDER_ID, null reference_code, null PHONE, null NAME, null EMAIL, null SHIPPING_LAST_UPDATE_DATE, null SKU, null PRODUCT_ID, null PRODUCT_NAME, null CURRENCY, CITY, State, null ORDER_STATUS, refund_date as Order_Date, null Order_Time, null QUANTITY, null GROSS_SALES_BEFORE_TAX, null GROSS_SALES_AFTER_TAX, null dis, null DISCOUNT, null TAX, null SHIPPING_PRICE, null SELLING_PRICE, null OMS_order_status, null SHIPPING_STATUS, null FINAL_SHIPPING_STATUS, null SALEORDERITEMCODE, null SALES_ORDER_ITEM_ID, null AWB, null PAYMENT_GATEWAY, null Payment_Mode, COURIER, null DISPATCH_DATE, null DELIVERED_DATE, null DELIVERED_STATUS, null RETURN_FLAG, null returned_quantity, null returned_sales, null cancelled_quantity, null Days_in_Shipment, null MARKETPLACE_ACQUISITION_DATE, null SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, null PRODUCT_SUB_CATEGORY, commonsku, null WAREHOUSE, null pincode, null source_pincode, null discount_codes, null nature, new_customer_flag, null new_customer_flag_month, null acquisition_product, null acquisition_channel, null acquisition_marketplace, null refund_date, null refund_value, null as cancelled_at, null as b2b_customer, refund_value as shopify_refund_value, tax as return_tax, reference_code as return_reference_code, null as final_channel_type, null as final_utm_campaign, child_sku, null as courier_aggregator, mapped_city, mapped_state, pack_type from maplemonk.prolicious_wh_sales_consolidated where (lower(marketplace) like \'%shopify%\' or lower(marketplace) like \'%website%\') and ifnull(refund_value,0) > 0 ) ; CREATE TABLE IF NOT EXISTS prolicious-wh.Maplemonk.prolicious_wh_easyecom_returns_intermediate ( ORDER_ID INT64, INVOICE_ID INT64, SUBORDER_ID STRING, REFERENCE_CODE STRING, CREDIT_NOTE_ID INT64, ORDER_DATE TIMESTAMP, INVOICE_DATE TIMESTAMP, RETURN_DATE TIMESTAMP, MANIFEST_DATE TIMESTAMP, IMPORT_DATE TIMESTAMP, LAST_UPDATE_DATE TIMESTAMP, COMPANY_PRODUCT_ID STRING, PRODUCTNAME STRING, PRODUCT_ID STRING, SKU STRING, MARKETPLACE STRING, MARKETPLACE_ID INT64, REPLACEMENT_ORDER INT64, RETURN_REASON STRING, RETURNED_QUANTITY FLOAT64, RETURN_AMOUNT_WITHOUT_TAX FLOAT64, RETURN_TAX FLOAT64, RETURN_SHIPPING_CHARGE FLOAT64, RETURN_MISC FLOAT64, TOTAL_RETURN_AMOUNT FLOAT64 ); CREATE OR REPLACE TABLE prolicious-wh.Maplemonk.prolicious_wh_easyecom_returns_fact_items AS SELECT IFNULL(FE.Source, \'NA\') AS Marketing_CHANNEL, FR.* FROM prolicious-wh.Maplemonk.prolicious_wh_easyecom_returns_intermediate FR LEFT JOIN ( SELECT DISTINCT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, Source FROM prolicious-wh.Maplemonk.prolicious_wh_sales_consolidated ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE WHERE lower(return_type) like \'customer return\'; CREATE OR REPLACE TABLE prolicious-wh.Maplemonk.prolicious_wh_returns_consolidated AS SELECT UPPER(er.MARKETPLACE) AS Marketplace, cast(RETURN_DATE as datetime) return_Date, UPPER(Marketing_CHANNEL) AS Marketing_channel, reference_code, saleorderitemcode, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(total_credit_note_amount) AS TOTAL_RETURN_AMOUNT, NULL AS TOTAL_RETURN_TAX, NULL AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM prolicious-wh.Maplemonk.prolicious_wh_easyecom_returns_fact_items er where lower(marketplace) not like \'%flipkart%\' GROUP BY er.Marketplace, RETURN_DATE, Marketing_channel,reference_code,saleorderitemcode union all select shop_name as marketplace, coalesce(er.return_date,f.order_service_completion_date) as return_date, \'FLIPKART\' as marketing_channel, f.order_id, f.line_item_id, sum(case when is_refund = 1 then quantity else 0 end) AS TOTAL_RETURNED_QUANTITY, SUM(case when is_refund = 1 then line_item_sales else 0 end) AS TOTAL_RETURN_AMOUNT, SUM(case when is_refund = 1 then tax else 0 end) AS TOTAL_RETURN_TAX, SUM(case when is_refund = 1 then cast(line_item_sales as float64) else 0 end) - SUM(case when is_refund = 1 then cast(tax as float64) else 0 end) AS TOTAL_RETURN_AMOUNT_EXCL_TAX from maplemonk.prolicious_flipkart_fact_items f LEFT JOIN ( select REFERENCE_CODE, saleorderitemcode, return_date from prolicious-wh.Maplemonk.prolicious_wh_easyecom_returns_fact_items where lower(marketplace) like \'%flipkart%\' qualify row_number() over (partition by REFERENCE_CODE,saleorderitemcode order by return_date desc) = 1 ) er on er.REFERENCE_CODE = f.order_id and f.line_item_id = er.saleorderitemcode where f.is_refund =1 group by 1,2,3,4,5;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            